-- Source-reviewed adaptations of IPA 2020-12-13 questions; additive only.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q17','exam-fe','スプーリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問17・改編】四つのジョブA〜Dを同時起動し、CPU多重度1でA→B→C→Dの順に実行する。実行時間と印刷時間はA=(50,50)、B=(30,40)、C=(20,30)、D=(40,20)秒。各ジョブの実行後、単一プリンタがスプーリング順に印刷する。全印刷が終了するのは起動後何秒か。','[{"id":"a","text":"100秒"},{"id":"b","text":"160秒"},{"id":"c","text":"190秒"},{"id":"d","text":"280秒"}]','"c"','CPU終了時刻は50、80、100、140秒。印刷は50〜100、100〜140、140〜170、170〜190秒となる。 中文：CPU和打印可并行，但单台打印机串行，最后190秒完成。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q21','exam-fe','アクチュエータ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問21・改編】アクチュエータの役割として適切なものはどれか。','[{"id":"a","text":"目標値と測定値を比較して操作量を決める"},{"id":"b","text":"位置や速度、温度などを検出して電気信号に変える"},{"id":"c","text":"制御信号に応じてエネルギーを回転や直線運動に変える"},{"id":"d","text":"マイクやセンサの微弱な電気信号を増幅する"}]','"c"','アクチュエータは制御信号を実際の機械的な動きに変える。 中文：执行器按控制信号把能量转化为运动；传感器负责检测。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q23','exam-fe','入力方式','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問23・改編】約200品目の商品を登録する画面で、プルダウン選択に適した項目はどれか。','[{"id":"a","text":"商品ごとに異なる5桁英数字の商品番号"},{"id":"b","text":"商品ごとに命名する40字以内の商品名"},{"id":"c","text":"あらかじめ5種類に定められた商品区分"},{"id":"d","text":"10,000〜100,000円の範囲にある6桁の価格"}]','"c"','固定された少数の候補から選ぶ商品区分が適する。 中文：五种固定分类适合下拉选择；名称、价格和商品编号的候选范围更大。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q25','exam-fe','関係データベース','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問25・改編】関係データベースのデータ構造を表す説明はどれか。','[{"id":"a","text":"親レコードと子レコードをポインタで結ぶ"},{"id":"b","text":"タグでデータ構造と意味を表す"},{"id":"c","text":"データと手続をカプセル化する"},{"id":"d","text":"データを二次元の表で表す"}]','"d"','関係データベースは行と列から成る表でデータを表現する。 中文：关系数据库用二维表表示数据；其他选项分别涉及层次、标记和对象。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q27','exam-fe','結合アルゴリズム','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問27・改編】RDBMSのソートマージ結合法を説明したものはどれか。','[{"id":"a","text":"一方の結合列の索引を使ってもう一方と結合する"},{"id":"b","text":"一方の結合列でハッシュ表を作って結合する"},{"id":"c","text":"一方の行を順に読み、他方の行と突き合わせる"},{"id":"d","text":"双方の結合列で並べ替え、先頭から順に照合する"}]','"d"','両表を結合キーで整列し、順に走査して一致する行を結合する。 中文：排序合并连接先按连接键排序，再顺序匹配。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q28','exam-fe','SQL副問合せ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問28・改編】商品(商品番号, 商品名, 単価)と在庫(倉庫番号, 商品番号, 在庫数)があり、商品番号は商品表の主キー、在庫表では倉庫番号と商品番号が複合主キーである。SELECT 商品番号 FROM 商品 WHERE 商品番号 NOT IN (SELECT 商品番号 FROM 在庫) と同じ結果を得るSQLはどれか。','[{"id":"a","text":"SELECT 商品番号 FROM 在庫 WHERE EXISTS (SELECT 商品番号 FROM 商品)"},{"id":"b","text":"SELECT 商品番号 FROM 在庫 WHERE NOT EXISTS (SELECT 商品番号 FROM 商品)"},{"id":"c","text":"SELECT 商品番号 FROM 商品 WHERE EXISTS (SELECT 商品番号 FROM 在庫 WHERE 商品.商品番号 = 在庫.商品番号)"},{"id":"d","text":"SELECT 商品番号 FROM 商品 WHERE NOT EXISTS (SELECT 商品番号 FROM 在庫 WHERE 商品.商品番号 = 在庫.商品番号)"}]','"d"','在庫表に同じ商品番号の行が存在しない商品をNOT EXISTSで選ぶ。主キーの要素はNULLではない。 中文：筛选库存表中不存在对应商品编号的商品；主键字段非空。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q30','exam-fe','動画バッファ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問30・改編】192kビット/秒で再生する音声2.4Mバイトを128kビット/秒で受信しながら途切れずに再生したい。再生前に最低何秒バッファすればよいか。1M=1000k、1バイト=8ビットとする。','[{"id":"a","text":"50秒"},{"id":"b","text":"100秒"},{"id":"c","text":"150秒"},{"id":"d","text":"250秒"}]','"a"','総量19200kビット、再生時間100秒。再生中の不足分は(192−128)×100=6400kビットで、受信に50秒必要。 中文：播放100秒期间少收到6400k比特，预缓冲需50秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q31','exam-fe','CSMA/CD','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問31・改編】イーサネットのCSMA/CDを説明したものはどれか。','[{"id":"a","text":"各端末がキャリアを検知し、衝突時に再送する"},{"id":"b","text":"周波数を時間枠に分けて複数通信を行う"},{"id":"c","text":"RTS/CTSとACKを使って送受信を調整する"},{"id":"d","text":"巡回するトークンを受け取った端末だけが送信する"}]','"a"','送信前に媒体の状態を確認し、衝突を検出すると再送する。 中文：CSMA/CD先侦听媒介，发生冲突后再传。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q32','exam-fe','レイヤ2スイッチ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問32・改編】スイッチングハブ（レイヤ2スイッチ）の特徴はどれか。','[{"id":"a","text":"接続端末にIPアドレスを動的に割り当てる"},{"id":"b","text":"宛先MACアドレスに対応するポートへ転送する"},{"id":"c","text":"受信パケットを常に全ポートへ転送する"},{"id":"d","text":"ネットワーク層でパケットを分割する"}]','"b"','MACアドレス表を使って既知の宛先に対応するポートへ転送する。未知宛先などではフラッディングもある。 中文：交换机根据MAC地址表转发已知目的地址，未知目的地可能泛洪。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q34','exam-fe','NAPT','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問34・改編】複数のプライベートIP端末が一つのグローバルIPを共有してインターネットへ接続する仕組みはどれか。','[{"id":"a","text":"DHCP"},{"id":"b","text":"DNS"},{"id":"c","text":"NAPT"},{"id":"d","text":"RADIUS"}]','"c"','NAPTはIPアドレスとポート番号を変換し、複数端末によるグローバルIP共有を可能にする。 中文：NAPT通过地址和端口转换使多个终端共享公网IP。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q35','exam-fe','DNSキャッシュ汚染','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問35・改編】B社のDNSキャッシュにA社Webサイトの名前と攻撃者サーバXのIPの誤った対応が登録された。両社の従業員は各自の社内DNSを使う。Xへ誘導されるのはどれか。','[{"id":"a","text":"A社WebにアクセスするA社従業員"},{"id":"b","text":"A社WebにアクセスするB社従業員"},{"id":"c","text":"B社WebにアクセスするA社従業員"},{"id":"d","text":"B社WebにアクセスするB社従業員"}]','"b"','汚染されたB社DNSでA社サイトを名前解決する利用者が誤ったIPを受け取る。 中文：使用遭污染的B公司DNS访问A公司网站时，会解析到攻击者地址。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q36','exam-fe','ディジタル署名','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問36・改編】デジタル署名の署名鍵の使い方と目的として適切なものはどれか。','[{"id":"a","text":"受信者が署名鍵を使って暗号文を復号する"},{"id":"b","text":"送信者が署名鍵で暗号化し、改ざん箇所を特定する"},{"id":"c","text":"送信者が署名鍵で署名を作成し、送信者による署名であることを確認できるようにする"},{"id":"d","text":"送信者が署名鍵でメッセージを暗号化し、内容を秘匿する"}]','"c"','送信者の秘密鍵で署名し、対応する公開鍵で検証する。署名自体は内容の秘匿を目的としない。 中文：发送方用私钥签名，接收方用对应公钥验证；签名本身不提供保密。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q37','exam-fe','ポートスキャン','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問37・改編】攻撃者が侵入に先立ってポートスキャンを行う目的はどれか。','[{"id":"a","text":"攻撃後のシステムログに痕跡がないかを確認する"},{"id":"b","text":"取得できそうなアカウントを探す"},{"id":"c","text":"攻撃対象になり得る稼働中のサービスを調べる"},{"id":"d","text":"不正実行後に有用な利用者情報を探す"}]','"c"','ポートの応答から稼働サービスを推測する事前調査である。 中文：端口扫描用于事前发现可能可访问的服务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q38','exam-fe','ブルートフォース','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問38・改編】暗号解読におけるブルートフォース攻撃はどれか。','[{"id":"a","text":"平文と暗号文の組に対して鍵を総当たりする"},{"id":"b","text":"暗号の統計的な偏りを線形近似して解読する"},{"id":"c","text":"動作時の電磁波を観測して解読する"},{"id":"d","text":"異なる平文と暗号文の差を解析して解読する"}]','"a"','ブルートフォースは候補となる鍵を総当たりで試す方法。 中文：暴力破解通过穷举可能的密钥尝试解密。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q39','exam-fe','公開鍵暗号','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問39・改編】AがBの公開鍵で暗号化したメールをBとCに送った。公開鍵は全員が持ち、秘密鍵はそれぞれ本人だけが持つ。適切な結果はどれか。','[{"id":"a","text":"BだけがAの公開鍵で復号できる"},{"id":"b","text":"BだけがB自身の秘密鍵で復号できる"},{"id":"c","text":"BとCの双方がBの公開鍵で復号できる"},{"id":"d","text":"BとCがそれぞれ自分の秘密鍵で復号できる"}]','"b"','Bの公開鍵で暗号化したものは対応するBの秘密鍵で復号する。 中文：使用B的公钥加密后，只有持有对应私钥的B能解密。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
